const body = $json.body || $json;
const required = ['run_id','account_id','website_url'];
const missing = required.filter((key) => !body[key]);
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
const expected = $vars.N8N_WEBHOOK_SECRET;
const supplied = $json.headers?.['x-workflow-secret'];
if (expected && supplied !== expected) throw new Error('Invalid workflow secret');
return [{ json: { ...body, evaluation_mode: false } }];

const input = $('Validate Production Input').item.json;
const crawlId = $json.id || $json.data?.id || null;
const providerError = $json.error?.message || $json.message || null;
return [{json:{...input,crawl_id:crawlId,crawl_status_url:crawlId?`https://api.firecrawl.dev/v2/crawl/${crawlId}`:null,poll_attempt:0,crawl_status:crawlId?'queued':'failed',crawl_error:providerError || (crawlId?null:'Firecrawl did not return a crawl job id'),crawl_response:null}}];

const prior = $('Wait Before Crawl Poll').item.json;
const response = $json || {};
const attempt = Number(prior.poll_attempt || 0) + 1;
const providerError = response.error?.message || response.message || null;
const status = String(response.status || response.data?.status || (providerError ? 'failed' : 'unknown')).toLowerCase();
const complete = status === 'completed';
const terminalFailure = status === 'failed' || Boolean(providerError) || attempt >= 60;
return [{json:{...prior,poll_attempt:attempt,crawl_status:status,crawl_complete:complete,crawl_terminal_failure:terminalFailure,crawl_error:providerError || (attempt>=60&&!complete?'Firecrawl polling timed out after 5 minutes':null),crawl_response:response}}];

const response = $json.crawl_response || $json || {};
const pages = Array.isArray(response.data) ? response.data : Array.isArray(response.data?.data) ? response.data.data : [];
const compact = pages.slice(0,25).map((page, index) => ({ source_key: `src_${index+1}`, url: page.metadata?.sourceURL || page.metadata?.url || page.url, title: page.metadata?.title || `Source ${index+1}`, source_type: String(page.metadata?.sourceURL || page.metadata?.url || page.url || '').toLowerCase().endsWith('.pdf') ? 'pdf' : 'web', markdown: String(page.markdown || page.content || '').slice(0,18000), retrieved_at: new Date().toISOString() }));
const partial = Boolean($json.crawl_error || $json.crawl_terminal_failure || response.next || !pages.length);
return [{ json: { ...$('Validate Production Input').item.json, evidence: { pages: compact, crawl_id: $json.crawl_id || null, crawl_status: $json.crawl_status || response.status || 'failed', crawl_partial: partial, crawl_error: $json.crawl_error || response.error?.message || null, pages_attempted: Number(response.total || pages.length), pages_completed: Number(response.completed || pages.length) } } }];

const input = { ...$json };
input.evidence = input.evidence || { pages: [], crawl_partial: true, crawl_error: 'No evidence supplied' };
input.expected_tier = input.expected_tier ?? null;
input.expected_min_matches = Number(input.expected_min_matches || 0);
return [{ json: input }];

