const catalog = [
 {sku:'DEMO-TOM-001',name:'Processed tomato pulp — aseptic',category:'Processed tomatoes',terms:['tomato','tomato pulp','tomato base','tomato puree','crushed tomato']},
 {sku:'DEMO-RIC-001',name:'Food-service long-grain rice',category:'Rice',terms:['rice','jasmine rice','long-grain rice','basmati rice']},
 {sku:'DEMO-VEG-001',name:'Dehydrated onion flakes',category:'Dehydrated vegetables',terms:['onion','onion flakes','dried onion']},
 {sku:'DEMO-VEG-002',name:'Dehydrated garlic granules',category:'Dehydrated vegetables',terms:['garlic','garlic granules','dried garlic']},
 {sku:'DEMO-PAS-001',name:'Italian penne rigate',category:'Italian pasta',terms:['pasta','penne','penne rigate']},
 {sku:'DEMO-SEA-001',name:'Bulk curry seasoning blend',category:'Starches and seasonings',terms:['seasoning','spice','curry']}
];
const raw = typeof query === 'string' ? query : JSON.stringify(query);
const q = raw.toLowerCase();
return JSON.stringify(catalog.filter(item => item.terms.some(term => q.includes(term))).slice(0,5));

const context = $('Prepare Agent Input').item.json;
const raw = $json.output ?? $json;
let result;
try { result = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (error) { return [{ json: { ...context, agent_valid: false, validation_errors: ['Agent output was not valid JSON'], status: 'failed_partial' } }]; }
const problems = [];
const evidencePages = context.evidence?.pages || [];
if (!evidencePages.length) problems.push('No research evidence pages were available');
for (const finding of result.findings || []) {
  if (!['observed','inferred','hypothesis'].includes(finding.evidence_strength)) problems.push(`Invalid evidence strength: ${finding.label}`);
  if (!(finding.source_keys || []).length) problems.push(`Finding lacks source: ${finding.label}`);
}
const allowedSources = new Set(evidencePages.map(page => page.source_key));
for (const finding of result.findings || []) {
  for (const key of finding.source_keys || []) if (!allowedSources.has(key)) problems.push(`Unknown source key ${key}: ${finding.label}`);
}
const clamp=(value,max)=>Math.max(0,Math.min(max,Number(value)||0));
const s=result.score_inputs||{};
const parts={product_applicability:clamp(s.product_applicability,40),evidence_specificity:clamp(s.evidence_specificity,25),scale_fit:clamp(s.scale_fit,20),supply_feasibility:clamp(s.supply_feasibility,15),risk_penalty:Math.max(-30,Math.min(0,Number(s.risk_penalty)||0))};
if (!evidencePages.length) Object.assign(parts,{product_applicability:0,evidence_specificity:0,scale_fit:0,supply_feasibility:0,risk_penalty:-30});
parts.total=Math.max(0,Math.min(100,parts.product_applicability+parts.evidence_specificity+parts.scale_fit+parts.supply_feasibility+parts.risk_penalty));
parts.tier=parts.total>=75?'qualified':parts.total>=55?'review':'disqualified';
const range=(m,a,k)=>{if(![m,a,k].every(v=>Number(v)>0)) return {status:'insufficient_evidence'}; const annual=Number(m)*Number(a)*Number(k); const p=v=>({weekly:Math.round(v/52),monthly:Math.round(v/12),annual:Math.round(v)}); return {status:'estimated',low:p(annual*.75),base:p(annual),high:p(annual*1.25)};};
result.ingredient_matches=(result.ingredient_matches||[]).map(match=>({...match,forecast:range(match.quantity_inputs?.meals_annual,match.quantity_inputs?.applicable_share,match.quantity_inputs?.kg_per_meal)}));
return [{json:{...context,...result,score:parts,agent_valid:problems.length===0,validation_errors:[...new Set(problems)],status:problems.length?'failed_partial':'completed',intermediateSteps:$json.intermediateSteps||[]}}];
